"use client"

import { useState, useEffect } from "react"
import { useRouter } from "next/navigation"
import { 
  ChartPieSlice, 
  Target, 
  PlusCircle, 
  Wallet, 
  ArrowUp, 
  ArrowDown, 
  Calendar,
  Lock,
  Tag,
  Trash,
  CheckCircle,
  CurrencyCircleDollar,
  SignOut
} from "@phosphor-icons/react"

import { Button } from "@/components/ui/button"
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"

// --- INTERFACES ---
interface Meta {
  id: string;
  titulo: string;
  valorAlvo: number;
  valorAtual: number;
}

interface Transacao {
  id: string;
  tipo: "receita" | "despesa";
  descricao: string;
  categoria: string;
  valor: number;
  data: string;
}

export default function DashboardHubPage() {
  const router = useRouter()
  
  // Controle da Aba Ativa: "home" | "metas" | "gastos"
  const [activeTab, setActiveTab] = useState<"home" | "metas" | "gastos">("home")

  // --- ESTADOS GLOBAIS (DADOS EM CACHE) ---
  const [metas, setMetas] = useState<Meta[]>([])
  const [transacoes, setTransacoes] = useState<Transacao[]>([])

  // --- ESTADOS DOS FORMULÁRIOS ---
  // Form Metas
  const [metaTitulo, setMetaTitulo] = useState("")
  const [metaValorAlvo, setMetaValorAlvo] = useState("")
  const [metaValorAtual, setMetaValorAtual] = useState("")
  // Form Gastos
  const [gastoTipo, setGastoTipo] = useState<"receita" | "despesa">("despesa")
  const [gastoDescricao, setGastoDescricao] = useState("")
  const [gastoCategoria, setGastoCategoria] = useState("")
  const [gastoValor, setGastoValor] = useState("")
  const [gastoData, setGastoData] = useState("")

  // --- CONTROLE DE TEMPO (GASTOS) ---
  const obterMesAtual = () => {
    const hoje = new Date()
    return `${hoje.getFullYear()}-${String(hoje.getMonth() + 1).padStart(2, '0')}`
  }
  const mesAtualSistema = obterMesAtual()
  const [mesSelecionado, setMesSelecionado] = useState<string>(mesAtualSistema)
  const podeEditarGastos = mesSelecionado === mesAtualSistema

  // --- CARREGAR CACHE (useEffect) ---
  useEffect(() => {
    // Carrega Metas
    const cachedMetas = localStorage.getItem("@salve:metas")
    if (cachedMetas) setMetas(JSON.parse(cachedMetas))
    else {
      const initMetas = [{ id: "1", titulo: "Reserva de Emergência", valorAlvo: 5000, valorAtual: 1500 }]
      setMetas(initMetas)
      localStorage.setItem("@salve:metas", JSON.stringify(initMetas))
    }

    // Carrega Gastos
    const cachedGastos = localStorage.getItem("@salve:gastos")
    if (cachedGastos) setTransacoes(JSON.parse(cachedGastos))
    else {
      const initGastos = [
        { id: "1", tipo: "receita", descricao: "Dia de Pagamento", categoria: "Receita", valor: 3500, data: `${mesAtualSistema}-05` },
        { id: "2", tipo: "despesa", descricao: "iFood Fim de Semana", categoria: "Alimentação (iFood/Comida)", valor: 89.90, data: `${mesAtualSistema}-10` }
      ]
      localStorage.setItem("@salve:gastos", JSON.stringify(initGastos))
    }
  }, [mesAtualSistema])

  // --- FUNÇÕES DE MANIPULAÇÃO ---
  const salvarMetas = (novas: Meta[]) => {
    setMetas(novas)
    localStorage.setItem("@salve:metas", JSON.stringify(novas))
  }

  const salvarGastos = (novas: Transacao[]) => {
    setTransacoes(novas)
    localStorage.setItem("@salve:gastos", JSON.stringify(novas))
  }

  const handleCriarMeta = (e: React.FormEvent) => {
    e.preventDefault()
    if (!metaTitulo || !metaValorAlvo) return
    const nova = {
      id: Date.now().toString(),
      titulo: metaTitulo,
      valorAlvo: parseFloat(metaValorAlvo),
      valorAtual: metaValorAtual ? parseFloat(metaValorAtual) : 0
    }
    salvarMetas([...metas, nova])
    setMetaTitulo(""); setMetaValorAlvo(""); setMetaValorAtual("")
  }

  const handleAdicionarTransacao = (e: React.FormEvent) => {
    e.preventDefault()
    if (!gastoDescricao || !gastoValor || !gastoData) return
    const nova = {
      id: Date.now().toString(),
      tipo: gastoTipo,
      descricao: gastoDescricao,
      categoria: gastoTipo === "receita" ? "Receita" : (gastoCategoria || "Geral"),
      valor: parseFloat(gastoValor),
      data: gastoData
    }
    salvarGastos([...transacoes, nova])
    setGastoDescricao(""); setGastoCategoria(""); setGastoValor(""); setGastoData("")
  }

  // --- CÁLCULOS GLOBAIS ---
  const transacoesFiltradas = transacoes.filter(t => t.data.startsWith(mesSelecionado))
  const totalRecebidoMes = transacoesFiltradas.filter(t => t.tipo === "receita").reduce((a, c) => a + c.valor, 0)
  const totalGastoMes = transacoesFiltradas.filter(t => t.tipo === "despesa").reduce((a, c) => a + c.valor, 0)
  const saldoRestanteMes = totalRecebidoMes - totalGastoMes

  const totalMetasSalvo = metas.reduce((a, c) => a + c.valorAtual, 0)
  const totalMetasAlvo = metas.reduce((a, c) => a + c.valorAlvo, 0)

  return (
    <div className="flex min-h-screen bg-gray-100 font-sans text-gray-800">
      
      <aside className="w-80 bg-[#670965] text-white flex flex-col p-6 shadow-xl shrink-0">
        <div className="mb-10">
          <h2 className="text-3xl font-black tracking-wider text-[#FF8A05]">$ALVE</h2>
          <p className="text-xs text-purple-200 uppercase tracking-widest font-semibold">Menu de Navegação</p>
        </div>

        {/* Abas de Navegação */}
        <nav className="space-y-2 flex-1">
          <button 
            onClick={() => setActiveTab("home")}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-bold transition-all ${activeTab === "home" ? "bg-white/10 text-[#FF8A05] border-l-4 border-[#FF8A05]" : "hover:bg-white/5 text-purple-100"}`}
          >
            <ChartPieSlice size={22} weight="bold" /> Visão Geral (Home)
          </button>

          <button 
            onClick={() => setActiveTab("metas")}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-bold transition-all ${activeTab === "metas" ? "bg-white/10 text-[#FF8A05] border-l-4 border-[#FF8A05]" : "hover:bg-white/5 text-purple-100"}`}
          >
            <Target size={22} weight="bold" /> Minhas Metas
          </button>

          <button 
            onClick={() => setActiveTab("gastos")}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-bold transition-all ${activeTab === "gastos" ? "bg-white/10 text-[#FF8A05] border-l-4 border-[#FF8A05]" : "hover:bg-white/5 text-purple-100"}`}
          >
            <Wallet size={22} weight="bold" /> Controle de Gastos
          </button>
        </nav>

        {/* Formulários Rápidos de Acordo com a Tela Aberta */}
        <div className="border-t border-purple-900/50 pt-6 mt-6">
          {activeTab === "metas" && (
            <form onSubmit={handleCriarMeta} className="space-y-3 bg-black/10 p-3 rounded-lg">
              <p className="text-xs font-bold text-[#FF8A05] uppercase">Rápido: Nova Meta</p>
              <Input placeholder="Objetivo" value={metaTitulo} onChange={e => setMetaTitulo(e.target.value)} required className="h-9 bg-white/10 border-none text-white text-xs placeholder-purple-300"/>
              <Input type="number" placeholder="Valor Alvo" value={metaValorAlvo} onChange={e => setMetaValorAlvo(e.target.value)} required className="h-9 bg-white/10 border-none text-white text-xs placeholder-purple-300"/>
              <Button type="submit" className="w-full bg-[#FF8A05] text-white font-bold h-9 text-xs uppercase">Cadastrar</Button>
            </form>
          )}

          {activeTab === "gastos" && podeEditarGastos && (
            <form onSubmit={handleAdicionarTransacao} className="space-y-3 bg-black/10 p-3 rounded-lg">
              <p className="text-xs font-bold text-[#FF8A05] uppercase">Rápido: Lançar Valor</p>
              <div className="grid grid-cols-2 gap-1">
                <button type="button" onClick={() => setGastoTipo("despesa")} className={`h-7 rounded text-[10px] font-bold uppercase ${gastoTipo === "despesa" ? "bg-[#FF8A05]" : "bg-white/10"}`}>Despesa</button>
                <button type="button" onClick={() => setGastoTipo("receita")} className={`h-7 rounded text-[10px] font-bold uppercase ${gastoTipo === "receita" ? "bg-green-600" : "bg-white/10"}`}>Receita</button>
              </div>
              <Input placeholder="Descrição" value={gastoDescricao} onChange={e => setGastoDescricao(e.target.value)} required className="h-9 bg-white/10 border-none text-white text-xs placeholder-purple-300"/>
              <Input type="number" placeholder="Valor R$" value={gastoValor} onChange={e => setGastoValor(e.target.value)} required className="h-9 bg-white/10 border-none text-white text-xs placeholder-purple-300"/>
              <Input type="date" value={gastoData} onChange={e => setGastoData(e.target.value)} required className="h-9 bg-white/10 border-none text-white text-xs [color-scheme:dark]"/>
              <Button type="submit" className="w-full bg-[#FF8A05] text-white font-bold h-9 text-xs uppercase">Confirmar</Button>
            </form>
          )}

          {activeTab === "gastos" && !podeEditarGastos && (
            <div className="text-center p-3 bg-black/20 rounded-lg text-xs text-purple-200">
              <Lock size={20} className="mx-auto text-[#FF8A05] mb-1"/> Mês passado bloqueado para alterações.
            </div>
          )}

          <button onClick={() => router.push("/login")} className="flex items-center gap-2 text-purple-300 hover:text-white text-xs mt-6 w-full justify-center">
            <SignOut size={16} /> Sair do Sistema
          </button>
        </div>
      </aside>

      {/* ================= ÁREA DE CONTEÚDO PRINCIPAL (DINÂMICO) ================= */}
      <main className="flex-1 p-8 md:p-12 overflow-y-auto">
        
        {/* 1. TELA: HOME (VISÃO GERAL) */}
        {activeTab === "home" && (
          <div className="space-y-8">
            <div>
              <h1 className="text-3xl font-black uppercase text-gray-800 tracking-tight">Bem-vindo ao $ALVE</h1>
              <p className="text-gray-500 text-sm">Resumo geral da sua saúde financeira combinada no mês atual.</p>
            </div>

            {/* Caixinhas de Valor da Home */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <Card className="border-l-4 border-[#670965] bg-white shadow-sm">
                <CardHeader className="flex flex-row items-center justify-between pb-2">
                  <CardTitle className="text-xs font-bold text-gray-400 uppercase">Saldo Restante (Mês)</CardTitle>
                  <CurrencyCircleDollar size={24} className="text-[#670965]" weight="fill" />
                </CardHeader>
                <CardContent>
                  <div className={`text-2xl font-black ${saldoRestanteMes >= 0 ? "text-gray-800" : "text-red-600"}`}>
                    R$ {saldoRestanteMes.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                  </div>
                  <p className="text-xs text-gray-400 mt-1">Ganhos menos gastos deste mês</p>
                </CardContent>
              </Card>

              <Card className="border-l-4 border-[#FF8A05] bg-white shadow-sm">
                <CardHeader className="flex flex-row items-center justify-between pb-2">
                  <CardTitle className="text-xs font-bold text-gray-400 uppercase">Total Acumulado em Metas</CardTitle>
                  <Target size={24} className="text-[#FF8A05]" weight="fill" />
                </CardHeader>
                <CardContent>
                  <div className="text-2xl font-black text-gray-800">
                    R$ {totalMetasSalvo.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                  </div>
                  <p className="text-xs text-gray-400 mt-1">De um total alvo de R$ {totalMetasAlvo.toLocaleString('pt-BR')}</p>
                </CardContent>
              </Card>

              <Card className="border-l-4 border-green-500 bg-white shadow-sm">
                <CardHeader className="flex flex-row items-center justify-between pb-2">
                  <CardTitle className="text-xs font-bold text-gray-400 uppercase">Total Recebido (Mês)</CardTitle>
                  <ArrowUp size={24} className="text-green-500" weight="bold" />
                </CardHeader>
                <CardContent>
                  <div className="text-2xl font-black text-green-600">
                    R$ {totalRecebidoMes.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                  </div>
                  <p className="text-xs text-gray-400 mt-1">Lançamentos de entrada</p>
                </CardContent>
              </Card>
            </div>

            {/* Atalho/Visão interna das Metas na Home */}
            <div className="bg-white p-6 rounded-xl border shadow-sm">
              <div className="flex justify-between items-center mb-4">
                <h3 className="font-bold text-lg uppercase text-gray-700 tracking-tight flex items-center gap-2">
                  <Target size={20} className="text-[#670965]"/> Progresso dos Seus Sonhos
                </h3>
                <button onClick={() => setActiveTab("metas")} className="text-xs font-bold text-[#FF8A05] hover:underline">Ver todas →</button>
              </div>
              <div className="space-y-4">
                {metas.slice(0, 3).map(m => {
                  const pct = Math.min(Math.round((m.valorAtual / m.valorAlvo) * 100), 100)
                  return (
                    <div key={m.id} className="space-y-1">
                      <div className="flex justify-between text-xs font-bold">
                        <span>{m.titulo}</span>
                        <span className="text-gray-500">{pct}% ({m.valorAtual} / {m.valorAlvo})</span>
                      </div>
                    </div>
                  )
                })}
              </div>
            </div>
          </div>
        )}

        {/* 2. TELA: CONTROLE DE METAS */}
        {activeTab === "metas" && (
          <div className="space-y-6">
            <div className="flex items-center gap-2">
              <Target size={28} className="text-[#670965]" weight="bold" />
              <h2 className="text-2xl font-black text-gray-800 uppercase tracking-tight">Dashboard de Metas</h2>
            </div>

            <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
              {metas.map(meta => {
                const pct = Math.min(Math.round((meta.valorAtual / meta.valorAlvo) * 100), 100)
                return (
                  <Card key={meta.id} className="bg-white relative shadow-sm overflow-hidden border-gray-100">
                    <div className={`h-1.5 ${pct >= 100 ? 'bg-green-500' : 'bg-[#FF8A05]'}`} />
                    <CardHeader className="flex flex-row items-start justify-between pb-2">
                      <div>
                        <CardTitle className="text-lg font-bold text-gray-800 flex items-center gap-2">
                          {meta.titulo}
                          {pct >= 100 && <CheckCircle size={20} className="text-green-500" weight="fill" />}
                        </CardTitle>
                        <CardDescription className="text-xs">Meta ativa de acumulação</CardDescription>
                      </div>
                      <button onClick={() => salvarMetas(metas.filter(m => m.id !== meta.id))} className="text-gray-400 hover:text-red-500"><Trash size={18} /></button>
                    </CardHeader>
                    <CardContent className="space-y-2">
                      <div className="flex justify-between items-baseline text-xs font-bold">
                        <span className="text-gray-400 uppercase">Progresso</span>
                        <span>R$ {meta.valorAtual.toLocaleString('pt-BR')} / R$ {meta.valorAlvo.toLocaleString('pt-BR')}</span>
                      </div>
                        <div className="w-full bg-gray-200 rounded-full h-3">
                          <div className={`h-3 rounded-full ${pct >= 100 ? 'bg-green-500' : 'bg-[#FF8A05]'}`} style={{ width: `${pct}%` }} />
                        </div>
                    </CardContent>
                  </Card>
                )
              })}
            </div>
          </div>
        )}

        {/* 3. TELA: CONTROLE DE GASTOS */}
        {activeTab === "gastos" && (
          <div className="space-y-6">
            <div className="flex justify-between items-center">
              <h2 className="text-2xl font-black text-gray-800 uppercase tracking-tight flex items-center gap-2">
                <Calendar size={28} className="text-[#670965]" /> Controle Mensal de Gastos
              </h2>
              <div className="flex items-center gap-2 bg-white p-2 rounded-lg border shadow-sm text-sm">
                <span className="text-xs font-bold text-gray-400 uppercase">Mês:</span>
                <input type="month" value={mesSelecionado} onChange={e => setMesSelecionado(e.target.value)} className="font-bold border-none text-gray-800 focus:outline-none cursor-pointer" />
              </div>
            </div>

            {/* Extrato/Tabela Comercial de lançamentos */}
            <div className="bg-white rounded-xl shadow-sm border p-6">
              <h3 className="text-sm font-bold text-gray-400 uppercase tracking-wider mb-4">Histórico de Lançamentos</h3>
              {transacoesFiltradas.length === 0 ? (
                <div className="text-center py-10 text-gray-400 text-sm">Nenhum gasto ou receita registrado neste mês.</div>
              ) : (
                <div className="divide-y divide-gray-100">
                  {transacoesFiltradas.map(t => (
                    <div key={t.id} className="flex items-center justify-between py-3">
                      <div className="flex items-center gap-3">
                        <div className={`w-8 h-8 rounded-full flex items-center justify-center ${t.tipo === 'receita' ? 'bg-green-100 text-green-600' : 'bg-orange-100 text-[#FF8A05]'}`}>
                          {t.tipo === 'receita' ? <ArrowUp size={16} /> : <ArrowDown size={16} />}
                        </div>
                        <div>
                          <p className="font-bold text-sm text-gray-800">{t.descricao}</p>
                          <span className="text-[10px] bg-gray-100 text-gray-500 font-bold px-1.5 py-0.5 rounded">{t.categoria}</span>
                        </div>
                      </div>
                      <div className="flex items-center gap-3">
                        <span className={`font-black text-sm ${t.tipo === 'receita' ? 'text-green-600' : 'text-gray-800'}`}>
                          {t.tipo === 'receita' ? '+' : '-'} R$ {t.valor.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                        </span>
                        {podeEditarGastos && (
                          <button onClick={() => salvarGastos(transacoes.filter(x => x.id !== t.id))} className="text-gray-300 hover:text-red-500"><Trash size={14} /></button>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        )}

      </main>
    </div>
  )
}